// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
return [{
  json: {
    // ── aus der Data Table pw_config ──
    paperless_url: pw('paperless_url'),
    // paper-werk prüft, ob eine E-Rechnung im PDF steckt. Im Stack der
    // Docker-Servicename, nicht die Browser-Adresse.
    paperwerk_url: String(pw('paperwerk_url')).replace(/\/+$/, ''),

    // ── fachlich ──
    // tag_kommando: der Auftrag; der Paperless-Ablauf "Rechnungsfelder
    //   erkennen" löst bei diesem Tag aus.
    // tag_pending: global. Solange er hängt, ruht JEDE Verarbeitung dieses
    //   Dokuments; so feuert das Zurückschreiben der Felder den Ablauf
    //   nicht erneut.
    // tag_erechnung: kennzeichnet eine erkannte E-Rechnung. Er lenkt später
    //   den Übertrag auf das XML (paper-werk-eingangsrechnung).
    tag_kommando: 'rechnung-erkennen',
    tag_pending: 'wird bearbeitet',
    tag_erechnung: 'E-Rechnung',
  }
}];

// Dokument-ID aus dem Paperless-Aufruf. Wirft bewusst nicht, wenn keine
// dabei ist; dann endet der Workflow ohne Meldung (siehe handschrift-ocr-titel-mistral).
const body = $('Webhook').first().json.body ?? {};
let id = body.doc_id ?? body.id;
if (!id && body.doc_url) {
  id = String(body.doc_url).match(/\/documents\/(\d+)/)?.[1];
}
return [{ json: {
  doc_id: id ? Number(id) : null,
  grund: id ? null : 'Aufruf ohne Dokument-ID. Nichts zu tun.',
} }];

// Ist dieser Lauf zuständig? Geschaut wird auf den ECHTEN Dokumentzustand,
// nicht auf eine Absprache mit Paperless. Eine geänderte
// Auslöser-Konfiguration erzeugt so höchstens Leerläufe, keine Schleifen.
const cfg = $('Konfiguration').first().json;
const alle = $('Tags laden').first().json.results ?? [];
const doc = $input.first().json;

const finde = (name) => {
  const t = alle.find((x) => String(x.name).toLowerCase() === String(name).toLowerCase());
  if (!t) {
    throw new Error('In Paperless gibt es kein Schlagwort "' + name + '". '
      + 'In paper-werk anlegen lassen: manage.py paperless_einrichten');
  }
  return t.id;
};
const kommando = finde(cfg.tag_kommando);
const pending = finde(cfg.tag_pending);
const erechnung = finde(cfg.tag_erechnung);
const hat = (id) => (doc.tags ?? []).includes(id);

let grund = null;
if (!hat(kommando)) {
  grund = 'Dokument trägt "' + cfg.tag_kommando + '" nicht mehr. Nichts zu tun.';
} else if (hat(pending)) {
  grund = 'Dokument ist als "' + cfg.tag_pending + '" markiert; es läuft bereits eine Verarbeitung. Nichts zu tun.';
}

return [{ json: {
  doc_id: doc.id,
  zustaendig: grund === null,
  grund,
  tag_kommando_id: kommando,
  tag_pending_id: pending,
  tag_erechnung_id: erechnung,
} }];

// Die Werte aus dem XML, in derselben Form wie "Extract entities" sie
// für Mistral liefert, damit der Rest des Workflows beide Wege gleich
// behandelt. paper-werk nennt die Felder schon beim Paperless-Namen:
// Rechnungsnummer, Rechnungsdatum, Nettobetrag, Gesamtbetrag, Fällig am
// und die Projektnummer, wenn die Projektreferenz eindeutig passt.
const befund = $input.first().json;
const doc = $('Get Document').first().json;
const entities = { ...(befund.felder ?? {}) };
return [{
  json: {
    id: doc.id,
    existingCustomFields: doc.custom_fields ?? [],
    entityNames: Object.keys(entities),
    entities,
    has_entity: true,
    erechnung: true,
  },
}];

// Das Dokument beim Namen und nicht über $input: Kommt der Lauf von der
// E-Rechnungs-Prüfung (keine oder keine lesbare E-Rechnung), liegt dort
// die Antwort von paper-werk.
const doc = $('Get Document').first().json;
const content = (doc.content ?? '').trim();
if (!content) throw new Error('Dokument hat keinen Text (content leer)');
return [{ json: { id: doc.id, content, existingCustomFields: doc.custom_fields ?? [] } }];

// ============================================================
// WELCHE FELDER extrahiert werden: zwei Wege, und der erste gewinnt.
//
// 1. Aus dem Webhook-Body: { "felder": { "Nettobetrag": "Beschreibung", ... } }
//    Damit entscheidet der AUFRUFER, was er braucht. Ein Paperless-Workflow
//    fuer Laborrechnungen fragt nach anderen Feldern als einer fuer
//    Versicherungspost, ohne dass dieser Workflow dafuer angefasst wird.
//
// 2. Ohne Angabe gelten die VORGABEN unten: die Felder, die der Übertrag
//    an paper-werk braucht. Der Regelfall.
//
// Schluessel  = Name des Custom Fields in Paperless (Suche case-insensitive).
// Wert        = Beschreibung fuer das Modell (was ist gemeint, welches Format).
// Das Custom Field muss in Paperless existieren.
// ============================================================
const VORGABEN = {
  'Nettobetrag': 'Der Rechnungsbetrag OHNE Umsatzsteuer. Nur die Zahl, mit Punkt als Dezimaltrenner und ohne Tausenderpunkte (also "1758.00").',
  'Gesamtbetrag': 'Der Rechnungsbetrag MIT Umsatzsteuer, also der Betrag, der zu zahlen ist. Format wie beim Nettobetrag.',
  'Rechnungsnummer': 'Die Rechnungsnummer des Lieferanten, exakt wie sie auf dem Beleg steht (z. B. "AL-2026-08777").',
  'Rechnungsdatum': 'Das Rechnungsdatum im Format JJJJ-MM-TT (z. B. "2026-08-28").',
  'Projektnummer': 'Die Projektnummer bzw. das Projektkennzeichen (z. B. "2026-042"). Steht oft unter "Ihre Referenz" oder "Bauvorhaben".',
};
const MISTRAL_MODEL = 'mistral-small-latest';
const MAX_CONTENT_CHARS = 15000;
// ============================================================

const body = $('Webhook').first().json.body ?? {};
let gewuenscht = body.felder;

// **Auch als JSON-String, und das ist kein Luxus.** Ein
// Paperless-Arbeitsablauf sendet seine Parameter formular-kodiert; ein
// verschachteltes Objekt gibt es dort nicht. Wer aus Paperless heraus
// eigene Felder will, schickt sie deshalb als Zeichenkette:
//   params: { "felder": "{\"Nettobetrag\": \"Der Betrag ohne USt\"}" }
if (typeof gewuenscht === 'string' && gewuenscht.trim() !== '') {
  try {
    gewuenscht = JSON.parse(gewuenscht);
  } catch (e) {
    throw new Error('"felder" ist ein Text, aber kein gueltiges JSON: ' + e.message
      + '; erwartet wird {"Feldname": "Beschreibung", ...}');
  }
}

let ENTITIES;
if (gewuenscht === undefined || gewuenscht === null) {
  ENTITIES = VORGABEN;
} else {
  // Streng pruefen statt still auf die Vorgaben zurueckfallen: Wer "felder"
  // mitschickt, meint es; ein Tippfehler im Schluesselnamen soll auffallen
  // und nicht dazu fuehren, dass etwas ganz anderes extrahiert wird.
  if (typeof gewuenscht !== 'object' || Array.isArray(gewuenscht)) {
    throw new Error('"felder" muss ein Objekt sein: {"Feldname": "Beschreibung fuer das Modell", ...}');
  }
  const namen = Object.keys(gewuenscht);
  if (namen.length === 0) {
    throw new Error('"felder" ist leer, dann gibt es nichts zu extrahieren. Feld weglassen, um die Vorgaben zu benutzen.');
  }
  for (const name of namen) {
    const beschreibung = gewuenscht[name];
    if (typeof beschreibung !== 'string' || beschreibung.trim() === '') {
      throw new Error('Feld "' + name + '" braucht eine Beschreibung fuer das Modell (ein nicht-leerer Text). Ohne sie raet Mistral, was gemeint ist.');
    }
  }
  ENTITIES = gewuenscht;
}

const src = $('Extract content').first().json;
const entityNames = Object.keys(ENTITIES);

const fieldList = entityNames
  .map((name) => `- "${name}": ${ENTITIES[name]}`)
  .join('\n');

const jsonSkeleton = '{' + entityNames.map((n) => `"${n}": "..."`).join(', ') + '}';

const SYSTEM_PROMPT = `Du bist ein Assistent zur Datenextraktion aus Dokumenten in einem Paperless-Dokumentenmanagementsystem. Du bekommst den OCR-Volltext eines Dokuments und extrahierst daraus definierte Felder.

Zu extrahierende Felder:
${fieldList}

Regeln:
- Übernimm den Wert exakt so, wie er im Dokument steht (gleiche Schreibweise, Bindestriche, Schrägstriche)
- Gib nur den Wert selbst zurück, ohne Beschriftung davor (also "RE-2026-0042", nicht "Rechnungsnummer: RE-2026-0042")
- Ist ein Feld im Dokument nicht vorhanden oder bist du unsicher, gib null zurück; erfinde niemals Werte
- Kommt ein Feld mehrfach vor, nimm den Wert, der sich auf das Dokument selbst bezieht (z. B. die eigene Rechnungsnummer, nicht eine referenzierte fremde)
- Beträge ohne Währungszeichen und ohne Tausendertrennung, mit Punkt als Dezimaltrenner (also "1758.00", nicht "1.758,00 €")

Antworte ausschließlich mit gültigem JSON in genau diesem Format, mit genau diesen Schlüsseln und ohne weitere Felder:
${jsonSkeleton}
(Wert jeweils ein String oder null)`;

const contentExcerpt = src.content.slice(0, MAX_CONTENT_CHARS);

const userContent = `OCR-Volltext des Dokuments (Auszug, ggf. gekürzt):\n---\n${contentExcerpt}\n---\n\nExtrahiere nun die Felder und antworte als JSON.`;

return [{
  json: {
    id: src.id,
    existingCustomFields: src.existingCustomFields,
    entityNames,
    mistralBody: {
      model: MISTRAL_MODEL,
      response_format: { type: 'json_object' },
      temperature: 0,
      max_tokens: 300,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userContent },
      ],
    },
  },
}];

// Mistral-Antwort parsen und auf die konfigurierten Entitäten normalisieren.
const src = $('Prepare extraction').first().json;
const aiItem = $input.first().json;

let raw = aiItem?.choices?.[0]?.message?.content;
if (typeof raw !== 'string' || raw.trim() === '') {
  throw new Error('Keine Antwort von Mistral erhalten: ' + JSON.stringify(aiItem).slice(0, 500));
}

// Eventuelle Markdown-Zäune entfernen, dann JSON parsen.
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  throw new Error('Mistral-Antwort ist kein gültiges JSON: ' + raw.slice(0, 500));
}

// Schlüssel case-insensitive zuordnen, Werte säubern.
const lowerMap = {};
for (const [k, v] of Object.entries(parsed)) lowerMap[k.toLowerCase()] = v;

const entities = {};
for (const name of src.entityNames) {
  let v = parsed[name] ?? lowerMap[name.toLowerCase()] ?? null;
  if (typeof v === 'number') v = String(v);
  if (typeof v === 'string') {
    v = v.trim();
    if (v === '' || v.toLowerCase() === 'null') v = null;
  } else if (v !== null) {
    v = null;
  }
  entities[name] = v;
}

const has_entity = Object.values(entities).some((v) => v !== null);

return [{
  json: {
    id: src.id,
    existingCustomFields: src.existingCustomFields,
    entityNames: src.entityNames,
    entities,
    has_entity,
  },
}];

// Die Werte kommen von einem der beiden Wege: aus der E-Rechnung oder
// von Mistral.
const entityData = $('E-Werte übernehmen').isExecuted
  ? $('E-Werte übernehmen').first().json
  : $('Extract entities').first().json;
const allFields = $input.first().json.results ?? [];

function findFieldId(name) {
  const field = allFields.find(f => String(f.name).toLowerCase() === name.toLowerCase());
  return field ? field.id : null;
}

// Für jede gefundene Entität das passende Custom Field ermitteln.
const updates = [];
for (const name of entityData.entityNames) {
  const value = entityData.entities[name];
  if (value === null) continue;
  const fieldId = findFieldId(name);
  if (!fieldId) {
    throw new Error('Custom field "' + name + '" nicht in Paperless gefunden. Bitte unter Einstellungen > Benutzerdefinierte Felder anlegen (Typ Text).');
  }
  updates.push({ fieldId, value });
}

// Vorhandene Custom-Field-Werte behalten, nur die extrahierten überschreiben.
const updateIds = new Set(updates.map(u => u.fieldId));
const existingFields = entityData.existingCustomFields ?? [];
const otherFields = existingFields.filter(f => !updateIds.has(f.field));
const customFields = [
  ...otherFields,
  ...updates.map(u => ({ field: u.fieldId, value: u.value })),
];

return [{ json: { id: entityData.id, customFields, entities: entityData.entities,
  erechnung: entityData.erechnung === true } }];

return [{ json: {
  status: 'erledigt',
  doc_id: $('Zuständigkeit prüfen').first().json.doc_id,
  erechnung: $('Build PATCH body').first().json.erechnung,
} }];

// Ende ohne Meldung: kein Fehler, keine Mail. Der Aufruf gilt einem anderen Ablauf.
return [{ json: {
  status: 'übersprungen',
  grund: $json.grund ?? 'unbekannt',
  doc_id: $json.doc_id ?? null,
} }];
